INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17601, 'Isaiah 53:1', 'Isaiah', 53, 1, '&nbsp;زمونږ په پېغام چا يقين کړے دے؟ مالِک خُدائ خپل قوت په چا ظاهر کړے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17602, 'Isaiah 53:2', 'Isaiah', 53, 2, '&nbsp;د مالِک خُدائ په وړاندې زما خِدمت کوونکى داسې وده وکړه لکه څنګه چې يو نرم تېغ په زمکه جرړې نيسى. هغۀ څۀ شان شوکت او حُسن نۀ لرلو چې د هغې په وجه مونږ ورباندې پام کړے وے. او نۀ په کښې څۀ داسې کشش وو چې مونږ يې متاثره کړې وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17603, 'Isaiah 53:3', 'Isaiah', 53, 3, '&nbsp;خلقو هغۀ ته سپک وکتل او هغه يې رد کړو، هغه د درد او کړاؤ سره مخ شو. او خلقو به هغۀ ته دومره سپک کتل چې مخ به يې ترېنه اړولو. مونږ د هغۀ هيڅ قدر نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17604, 'Isaiah 53:4', 'Isaiah', 53, 4, '&nbsp;خو بې‌شکه چې هغۀ زمونږ بيمارۍ او کمزورۍ اوچتې کړې. خو بيا هم زمونږ دا خيال وو چې هغۀ له سزا ورکړے شوه، او دا چې خُدائ پاک هغه ووهلو او د هغۀ د ګناهونو سزا يې ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17605, 'Isaiah 53:5', 'Isaiah', 53, 5, '&nbsp;خو زمونږ د ګناه په وجه هغه زخمى شو، زمونږ د بغاوت په وجه هغه چخڼى کړے شو. چې کومه سزا ورکړے شوه نو د هغې په وجه مونږ ته شفا مِلاو شوه، هغۀ چې کوم وهل وخوړل نو د هغې په وجه مونږ روغ شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17606, 'Isaiah 53:6', 'Isaiah', 53, 6, '&nbsp;مونږ ټول د ورکو ګډو په شان يُو، مونږ د خُدائ پاک د لارې نه اوړېدلى يُو. هر يو کس په خپله مخه روان دے. خو بيا هم مالِک خُدائ زمونږ د ټولو ګناهونه په هغۀ باندې واچول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17607, 'Isaiah 53:7', 'Isaiah', 53, 7, '&nbsp;هغۀ باندې ظلم زياتے وشو، خو هغۀ په خولۀ باندې هيڅ هم ونۀ وئيل. لکه چې يو ګډُورے د حلالولو دپاره بوتلے شى، لکه چې يوه ګډه د وړۍ کلولو والا په مخکښې خاموش وى، نو هم هغه شان هغۀ د خولې نه يوه خبره هم نۀ ويستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17608, 'Isaiah 53:8', 'Isaiah', 53, 8, '&nbsp;هغه په دروغه مجرم وګرځولے شو او بوتلے شو. او هيچا د دې پرواه ونۀ ساتله چې هغه بې‌اولاده مړ شو، او هغه د ژوندو د زمکې نه لرې کړے شو. خو هغه زما د خلقو د ګناه په وجه ووژلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17609, 'Isaiah 53:9', 'Isaiah', 53, 9, '&nbsp;د هغوئ اراده وه چې د بدعمله خلقو سره يې ښخ کړى، خو هغه د مالداره سړى په قبر کښې کېښودلے شو، خو هغۀ هيڅ جرم هم نۀ وو کړے او نۀ يې څوک دوکه کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17610, 'Isaiah 53:10', 'Isaiah', 53, 10, '&nbsp;خو دا د مالِک خُدائ رضا وه چې هغه ووهلے شى، او درد ورته مِلاو شى. کله چې د هغۀ ژوند د ګناه دپاره کفاره شى، د هغۀ به ډېر اولاد وى. هغه به يو اوږد عُمر تېر کړى، او د هغۀ په ذريعه به د مالِک خُدائ مقصد پوره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17611, 'Isaiah 53:11', 'Isaiah', 53, 11, '&nbsp;کله چې هغه وګورى چې د هغۀ د مصيبت اوچتولو په وجه هغۀ څۀ حاصل کړى دى، نو هغه به مطمئن شى. زما صادق خِدمت کوونکے به ډېر خلق صادقان کړى، ځکه چې هغه به د هغوئ ګناهونه اوچت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17612, 'Isaiah 53:12', 'Isaiah', 53, 12, '&nbsp;نو زۀ به هغۀ له د عزت مقام ورکړم، او زۀ به د زورَورو سره مالِ غنيمت تقسيم کړم، ځکه چې هغۀ خپل ځان مرګ ته حواله کړو او هغه په باغيانو کښې حساب کړے شو. د ډېرو خلقو ګناه يې واخستله او د بدعملو د ګناه معافى يې وغوښتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17613, 'Isaiah 54:1', 'Isaiah', 54, 1, '&nbsp;مالِک خُدائ فرمائى، ”اے شنډې ښځې د چا چې اولاد نشته. د خوشحالۍ نه چغې ووهه، د خوشحالۍ نه سندرې ووايه، ولې چې تا د ماشوم د راوړو درد نۀ دے تېر کړے. ولې چې د شنډې ښځې بچى اوس د وادۀ شوې ښځې نه زيات دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17614, 'Isaiah 54:2', 'Isaiah', 54, 2, '&nbsp;تاسو چې په کومه خېمه کښې اوسېږئ هغه لويه کړئ او پړدې يې خوَرې کړئ، بچت مۀ کوئ، د خېمې پړى اوږدۀ کړئ او موږى يې کلک کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17615, 'Isaiah 54:3', 'Isaiah', 54, 3, '&nbsp;ځکه چې تاسو به خپل سرحدونه هر طرف ته خوارۀ کړئ، ستاسو اولاد به قومونه فتح کړى او چې کوم ښارونه خوشى دى نو هغه به دوباره آباد کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17616, 'Isaiah 54:4', 'Isaiah', 54, 4, '&nbsp;يرېږئ مۀ، تاسو به نور د شرم سره نۀ مخ کېږئ. شرمېږئ مۀ، تاسو به نۀ بې‌عزته کېږئ. تۀ به خپل د ځوانۍ شرم هېر کړې او د کونډېدو رسوائى به ستا د ذهن نه ختمه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17617, 'Isaiah 54:5', 'Isaiah', 54, 5, '&nbsp;ځکه چې ستاسو خالِق به ستاسو خاوند وى، د هغۀ نوم مالِک خُدائ ربُ الافواج دے. د بنى اِسرائيلو مقدس ذات ستاسو خلاصونکے دے، هغه د ټولې دُنيا خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17618, 'Isaiah 54:6', 'Isaiah', 54, 6, '&nbsp;مالِک خُدائ به تاسو بيا راوغواړى داسې لکه چې خاوند ښځه پرېښې وى او سخته پرېشانه وى. تاسو د داسې ښځې په شان يئ چې ځوانه وادۀ شوى وى او خاوند رد کړې وى. ستاسو خُدائ پاک داسې فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17619, 'Isaiah 54:7', 'Isaiah', 54, 7, '&nbsp;د يوې لحظې دپاره ما تاسو پرېښودلئ، خو اوس ډېر لوئ رحم سره به تاسو بيا راجمع کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17620, 'Isaiah 54:8', 'Isaiah', 54, 8, '&nbsp;ما د غصې په تاو کښې د لږ ساعت دپاره ستاسو نه مخ واړولو، خو زۀ به تل په مينې سره په تاسو رحم کوم.“ ستاسو خلاصونکے مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17621, 'Isaiah 54:9', 'Isaiah', 54, 9, '&nbsp;”لکه څنګه چې د نوح په وخت کښې ما وعده کړې وه چې بيا به هيڅکله په زمکه داسې سېلاب نۀ راځى. نو هغسې ما قسم کړے دے چې زۀ به بيا تاسو ته نۀ غصه کېږم، او نۀ به تاسو رټم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17622, 'Isaiah 54:10', 'Isaiah', 54, 10, '&nbsp;اګر کۀ غرونه لرې کړے شى او غونډۍ غېبې شى، خو زما وفاداره مينه به ستاسو سره هيڅکله نۀ ختميږى، او زما د امن لوظ به هيڅکله تاسو سره نۀ ختميږى.“ هغه مالِک خُدائ داسې فرمائى څوک چې په تاسو رحم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17623, 'Isaiah 54:11', 'Isaiah', 54, 11, '&nbsp;مالِک خُدائ فرمائى، ”اے يروشلمه، په تا سخت طوفان تېر شو او هيچا هم تسلى درنۀ کړے شوه. زۀ به تا د قيمتى کاڼو نه بيا آباد کړم او ستا بنيادونه به د نيلم کاڼو نه بيا جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17624, 'Isaiah 54:12', 'Isaiah', 54, 12, '&nbsp;ستا منارې به زۀ د ځلېدونکو عقيقو نه جوړې کړم، ستا دروازې به د پړقېدونکو لعلونو نه جوړې کړم، او ستا دېوالونه به د قيمتى کاڼو نه جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17625, 'Isaiah 54:13', 'Isaiah', 54, 13, '&nbsp;زۀ په خپله به ستاسو ټولو بچو ته ښودنه کوم، او هغوئ به خېر خېريت سره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17626, 'Isaiah 54:14', 'Isaiah', 54, 14, '&nbsp;ستا د بادشاهت بنياد به په اِنصاف باندې وى، د ظلم زياتى نه به په امان يې، نۀ به تۀ يرېږې، او نۀ به يره تا ته نزدې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17627, 'Isaiah 54:15', 'Isaiah', 54, 15, '&nbsp;کۀ څوک په تاسو باندې حمله کوى نو دا به زما د طرف نه نۀ وى. نو هر څوک چې ستاسو خِلاف جنګ کوى هغه به شکست خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17628, 'Isaiah 54:16', 'Isaiah', 54, 16, '&nbsp;ما لوهار پېدا کړے دے، څوک چې د هوا په ذريعه سکارۀ ګرموى او وسله جوړوى. د تباهۍ دپاره ما تباه کار هم پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17629, 'Isaiah 54:17', 'Isaiah', 54, 17, '&nbsp;داسې وسله به نۀ وى چې تاسو ته ضرر ورسوى، او څوک چې په تاسو اِلزام لګوى نو تاسو به د هغوئ خولې بندې کړئ. د مالِک خُدائ خادِمان به د دې فائدو نه خوند اخلى، زۀ به د هغوئ حق څرګند کړم.“ مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17630, 'Isaiah 55:1', 'Isaiah', 55, 1, '&nbsp;مالِک خُدائ فرمائى، ”هر څوک چې تږى وى، راشئ اوبۀ وڅښئ. څوک چې مال دولت نۀ لرى، نو راشئ، واخلئ او وې خورئ. راشئ، مے او پئ واخلئ، دا مفت دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17631, 'Isaiah 55:2', 'Isaiah', 55, 2, '&nbsp;چې په څۀ باندې تاسو نۀ مړېږئ نو په هغې باندې پېسې ولې خرچ کوئ؟ چې فائده نۀ درکوى نو په هغه خوراک پېسې ولې ورکوئ؟ غور سره ما ته غوږ شئ او ښۀ خوراک کوئ. تاسو به د ډېرو مزيدارو خوراکونو نه خوند واخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17632, 'Isaiah 55:3', 'Isaiah', 55, 3, '&nbsp;اوس غوږ ونيسئ او ما له راشئ، نو تاسو به ژوندى اوسئ. زۀ به تاسو سره يو نۀ ختمېدونکے لوظ وکړم او زۀ به تاسو له هغه نۀ ختمېدونکې مينه درکړم چې ما يې د داؤد سره لوظ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17633, 'Isaiah 55:4', 'Isaiah', 55, 4, '&nbsp;ګوره، ما هغه د قومونو ګواه جوړ کړو، ما هغه د قومونو مشر او فوجى آفسر جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17634, 'Isaiah 55:5', 'Isaiah', 55, 5, '&nbsp;اوس به تاسو د بل مُلک هغه قومونه راوغواړئ، چې په يو وخت کښې هغوئ تاسو نۀ پېژندئ، خو اوس به هغوئ په منډه منډه تاسو له راشى. زۀ مالِک خُدائ ستاسو خُدائ پاک، د بنى اِسرائيلو مقدس ذات به دا هر څۀ وکړم، او تاسو له به عزت درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17635, 'Isaiah 55:6', 'Isaiah', 55, 6, '&nbsp;د مالِک خُدائ لټون وکړئ کله چې هغه موندے شئ، هغۀ ته آواز وکړئ کله چې هغه نزدې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17636, 'Isaiah 55:7', 'Isaiah', 55, 7, '&nbsp;بدعمله خلق دې خپلې د ژوند طريقې بدلې کړى او شرپسند دې خپل خيالونه بدل کړى. او هغوئ دې مالِک خُدائ زمونږ خُدائ پاک ته راوګرځى، نو هغه رحم کوونکے دے او کولاو زړۀ سره معاف کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17637, 'Isaiah 55:8', 'Isaiah', 55, 8, '&nbsp;مالِک خُدائ فرمائى، ”زما خيالونه ستاسو د خيالونو په شان نۀ دى، او زما لارې ستاسو نه بدلې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17638, 'Isaiah 55:9', 'Isaiah', 55, 9, '&nbsp;لکه څنګه چې آسمانونه د زمکې نه اوچت دى، نو هم دغه شان زما لارې او سوچونه هم ستاسو نه اوچت دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17639, 'Isaiah 55:10', 'Isaiah', 55, 10, '&nbsp;لکه څنګه چې باران او واوره د آسمان نه راوريږى او هسې واپس نۀ ځې بلکې زمکه اوبۀ کوى. دې سره فصلونه راشنۀ کيږى زميندار له تخم او اوږى له خوراک ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17640, 'Isaiah 55:11', 'Isaiah', 55, 11, '&nbsp;زما کلام هم، هم دغسې دے. چې زما د خولې نه وځې نو خالى لاس به واپس نۀ راځى. دا به زما مرضى پوره کوى او په هغه هر څۀ کښې به کامياب وى د څۀ دپاره چې ما لېږلے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17641, 'Isaiah 55:12', 'Isaiah', 55, 12, '&nbsp;تاسو به خوشحالۍ سره وځئ، او سلامتۍ سره به بوتلے شئ. غرونه او د غرونو غونډۍ به په تېز آواز سندرې وائى، او په پټى کښې ټولې ونې به د خوشحالۍ نه لاسونه پړقوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17642, 'Isaiah 55:13', 'Isaiah', 55, 13, '&nbsp;چرته چې اوس د غنو بوټى دى نو هلته به د سبر ونې راوټوکيږى، او د ازغو په ځائ کښې به د نختر ونې راوټوکيږى. دې سره به د مالِک خُدائ نوم ته جلال ملاويږى، دا به د هغۀ د قدرت او د مينې يو نۀ ختمېدونکې نښه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17643, 'Isaiah 56:1', 'Isaiah', 56, 1, '&nbsp;مالِک خُدائ خپلو خلقو ته فرمائى چې، ”هغه څۀ کوئ څۀ چې صحيح او د اِنصاف دى، ولې چې زۀ زر راروان يم چې تاسو له خلاصون درکړم، او ستاسو مينځ کښې خپل صداقت څرګند کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17644, 'Isaiah 56:2', 'Isaiah', 56, 2, '&nbsp;بختور دى هغوئ چې په صداقت کلک ولاړ وى. بختور دى هغوئ چې د سبت د ورځې بې‌حرمتى نۀ کوى بلکې منى يې، او خپل ځانونه د بدعملۍ نه ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17645, 'Isaiah 56:3', 'Isaiah', 56, 3, '&nbsp;د پردى مُلک کوم خلق چې د مالِک خُدائ منونکى جوړ شوى دى نو هغوئ دې ونۀ وائى چې، ”مالِک خُدائ به مونږ خامخا د خپلو خلقو نه جدا کړى.“ او نۀ دې خصى وائى چې، ”زۀ خو اوچ بوټے يم، نۀ مې بچى شته او نۀ مستقبل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17646, 'Isaiah 56:4', 'Isaiah', 56, 4, '&nbsp;مالِک خُدائ فرمائى چې، ”کوم خصيان چې د سبت ورځې د منلو په وجه زما درناوے کوى او هغه کار کوى چې زۀ ورباندې رضا کېږم او زما په لوظ ټينګ ولاړ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17647, 'Isaiah 56:5', 'Isaiah', 56, 5, '&nbsp;نو زۀ به هغوئ له زما په خپل کور او د هغې چارديوارۍ کښې يو داسې يادګار او نوم ورکوم چې د لوڼو او زامنو نه به زيات ښۀ وى. او کوم نوم به چې زۀ هغوئ له ورکوم نو هغه به تل تر تله وى او هيڅکله به ختميږى نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17648, 'Isaiah 56:6', 'Isaiah', 56, 6, '&nbsp;او مالِک خُدائ د پردى مُلک هغه خلقو ته فرمائى چې کوم د هغۀ منونکى جوړ شوى دى، څوک چې د هغۀ سره مينه کوى او د هغۀ خِدمت کوى، کوم چې د سبت ورځ منى او د هغۀ په لوظ ټينګ ولاړ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17649, 'Isaiah 56:7', 'Isaiah', 56, 7, '&nbsp;نو زۀ به هغوئ خپل مقدس غر صيون ته راولم، او خپل د دُعا کور کښې به د هغوئ زړونه د خوشحالۍ نه ډک کړم. او زۀ به د هغوئ سوزېدونکې نذرانې او قربانۍ قبولې کړم. ځکه چې زما کور به د ټولو قومونو دپاره د دُعا کور بللے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17650, 'Isaiah 56:8', 'Isaiah', 56, 8, '&nbsp;مالِک خُدائ تعالىٰ، چا چې خپل خلق بنى اِسرائيليان د جلاوطنۍ نه راوستى دى هغه فرمائى چې هغه به نور خلق هم راجمع کړى هغوئ سره څوک چې مخکښې نه راجمع دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17651, 'Isaiah 56:9', 'Isaiah', 56, 9, '&nbsp;اے ټولو بلاګانو. اے د ځنګل ټولو بلاګانو راشئ. او زما خلق لواړ تېر کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17652, 'Isaiah 56:10', 'Isaiah', 56, 10, '&nbsp;زما د خلقو مشران لکه د محافظانو په شان دى څوک چې په سترګو ړاندۀ دى، او ټول د هيڅ نه هم نۀ دى خبر. هغوئ ټول د ګونګى سپى په شان دى او غپلے نۀ شى، هسې پراتۀ وى او خوبونه کوى. د هغوئ خوب ډېر خوښ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17653, 'Isaiah 56:11', 'Isaiah', 56, 11, '&nbsp;هغوئ د لالچى سپو په شان دى چې هيڅکله نۀ مړيږى. باوجود د دې چې هغوئ ته شپانۀ وئيلے شى خو هغوئ په هيڅ هم نۀ پوهيږى. هغوئ ټول په خپله مخه روان دى او خپلې ګټې پسې ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17654, 'Isaiah 56:12', 'Isaiah', 56, 12, '&nbsp;هغوئ وائى، ”راځئ چې مے واخلو او ځانونه پرې ښۀ په سور کښې کړُو. او سبا به د نن نه هم زياته خوشحالى کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17655, 'Isaiah 57:1', 'Isaiah', 57, 1, '&nbsp;صادق سړے مړ شى او هيڅ څوک يې پرواه نۀ ساتى. ديانتدار خلق د دُنيا نه اوچت کړے شى، خو هيڅوک پرې نۀ پوهيږى. هيڅوک پرې نۀ پوهيږى چې صادقان د بدۍ نه بچ کېدو دپاره دُنيا نه اوچت کړے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17656, 'Isaiah 57:2', 'Isaiah', 57, 2, '&nbsp;څوک چې د خُدائ پاک په لارو ژوند تېر کړى، او چې کله وفات شى نو ورته آرام او سکون ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17657, 'Isaiah 57:3', 'Isaiah', 57, 3, '&nbsp;خو اے د کوډګرې بچو، د زناکارې او کنجرې بچو، ديخوا راشئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17658, 'Isaiah 57:4', 'Isaiah', 57, 4, '&nbsp;تاسو چا پورې ټوقې کوئ؟ چا ته خپل بوتاړ وران کړئ او ژبې ورته راوباسئ؟ تاسو هم د دوکه بازو او ګناهګارو بچى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17659, 'Isaiah 57:5', 'Isaiah', 57, 5, '&nbsp;تاسو د بُتانو عبادت داسې کوئ چې د هر شين بوټے او د څېړۍ د مقدسو ونو لاندې زنا کوئ. تاسو د ګټو په غارونو کښې او واديانو کښې خپل بچى قربانى کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17660, 'Isaiah 57:6', 'Isaiah', 57, 6, '&nbsp;د واديانو هوار کاڼى ستاسو معبودان دى. تاسو دې ته د څښلو نذرانې تويَوئ او د غلې نذرانې ورته پېش کوئ. ستاسو خيال دا دے څۀ چې زۀ په دې هر څۀ باندې خوشحالېږم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17661, 'Isaiah 57:7', 'Isaiah', 57, 7, '&nbsp;تاسو په هر اوچت غر د پاسه زنا کړې ده. هلته تاسو بُتانو ته نذرانې پېش کړى دى او ما سره مو بې‌وفائى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17662, 'Isaiah 57:8', 'Isaiah', 57, 8, '&nbsp;تا د خپل کور په چوکاټونو او د دروازو شاته د بُتانو نښې ولګولې. زۀ دې پرېښودم او د نفرت نه ډکو بُتانو سره کټ ته اوختې. تا د هغوئ سره سودا کړې ده. د هغوئ بربنډو جسمونو ته کتل تا له خوند درکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17663, 'Isaiah 57:9', 'Isaiah', 57, 9, '&nbsp;تۀ د زيتُونو تېلو، او ډېرو عطرو سره مولک بُت له لاړې. د نوى معبودانو پېدا کولو دپاره چې مينه ورسره وکړې تا خپل پېغام وړُونکى لرې لرې تر دې چې عالمِ ارواح پورې دې ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17664, 'Isaiah 57:10', 'Isaiah', 57, 10, '&nbsp;د نورو معبودانو په لټولو کښې تاسو خپل ځانونه ستړى کړئ، خو تاسو هيڅکله نۀ وايئ چې، ”دا فضول دى.“ ستاسو شوق تاسو له طاقت درکوى نو ځکه تاسو ستړى کېږئ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17665, 'Isaiah 57:11', 'Isaiah', 57, 11, '&nbsp;تۀ د چا نه دومره سخت يرېدې چې تا ما ته دروغ ووئيل، نۀ دې زۀ ياد کړم او نۀ دې زما پرواه وکړه؟ زۀ چې دا دومره موده خاموش وم نو په دې وجه تۀ زما نه نۀ يرېږې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17666, 'Isaiah 57:12', 'Isaiah', 57, 12, '&nbsp;زۀ به ستا تش د نامې صداقت او کارونه خلقو ته څرګند کړم. او دا به ستا هيڅ په ښه نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17667, 'Isaiah 57:13', 'Isaiah', 57, 13, '&nbsp;کله چې تاسو د مدد دپاره آواز وکړئ، نو ستاسو هغه بُتان دې تاسو بچ کړى کنه. هوا به هغوئ اوچت کړى، د ساه يو پوکے به هغوئ يوسى. خو څوک چې په ما ايمان لرى نو هغه به د مُلک مالِک شى، او زما د مقدس غر وارث به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17668, 'Isaiah 57:14', 'Isaiah', 57, 14, '&nbsp;مالِک خُدائ فرمائى، ”لار جوړه کړئ، لار جوړه کړئ. دا تياره کړئ او زما د خلقو د لارې نه هر خنډ لرې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17669, 'Isaiah 57:15', 'Isaiah', 57, 15, '&nbsp;زۀ هغه مقدس خُدائ تعالىٰ يم، چې د همېشه دپاره ژوندے يم. زۀ په اوچت او مقدس مقام کښې اوسېږم، خو زۀ د هغه خلقو سره هم اوسېږم چې څوک د روح عاجزان او توبه ګار وى، نو چې داسې زۀ د هغوئ خوشحالى او حوصله بحال کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17670, 'Isaiah 57:16', 'Isaiah', 57, 16, '&nbsp;زۀ به همېشه خپلو خلقو سره جنګ نۀ کوم، او تل تر تله به ترېنه خفه نۀ يم. کۀ ما داسې وکړل نو د خلقو نه به ساه وځى، هغه ژوندون ورکوونکى ساه چې ما تخليق کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17671, 'Isaiah 57:17', 'Isaiah', 57, 17, '&nbsp;د هغوئ د بدترين لالچ په وجه زۀ هغوئ ته په قهر وم، نو په دې وجه ما هغوئ له سزا ورکړه او هغوئ مې رد کړل. خو هغوئ ضديان وُو او بيا بيا به خپلو لارو ته راواپس کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17672, 'Isaiah 57:18', 'Isaiah', 57, 18, '&nbsp;هغوئ چې څۀ کوى ما هغه ليدلى دى، خو باوجود د دې به زۀ هغوئ ښۀ کړم. زۀ به د هغوئ رهنمائى کوم او چې څوک غمژن وى نو زۀ به تسلى ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17673, 'Isaiah 57:19', 'Isaiah', 57, 19, '&nbsp;زۀ به د هغوئ په ژبه باندې د حمد و ثناء الفاظ راولم. کۀ څوک لرې وى او کۀ نزدې وى، نو زۀ به هغه ټولو ته امن پېش کوم، او زۀ به ورله شفا ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17674, 'Isaiah 57:20', 'Isaiah', 57, 20, '&nbsp;خو بدعمله خلق د چپې وهونکى سمندر په شان دى، چې هيڅکله په آرام کيږى نه او چپې يې ځان سره ګند ګريل راوړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17675, 'Isaiah 57:21', 'Isaiah', 57, 21, '&nbsp;زما مالِک خُدائ فرمائى، ”د بدعمله خلقو دپاره امن نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17676, 'Isaiah 58:1', 'Isaiah', 58, 1, '&nbsp;”په زوره چغې ووهئ، ورو ورو خبرې مۀ کوئ. د بيګل په شان په اوچت آواز سره زما خلقو بنى اِسرائيلو ته د هغوئ د ګناه او بغاوت په حقله ووايئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17677, 'Isaiah 58:2', 'Isaiah', 58, 2, '&nbsp;هغوئ هره ورځ زما لټون کوى او زما د لارې په پېژندلو خوشحاليږى. داسې لکه چې هغه يو ډېر صادق قوم وى او د خپل خُدائ پاک حُکمونه يې رد کړې نۀ وى. هغوئ زما نه د اِنصاف فېصلې غواړى، او داسې څرګندوى چې خُدائ پاک ته په نزدې راتلو خوشحاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17678, 'Isaiah 58:3', 'Isaiah', 58, 3, '&nbsp;هغوئ وائى، ”کله چې مونږ روژې نيسو نو تۀ پرې ولې نۀ خوشحالېږې؟ مونږ ځانونه دومره عاجز کړُو او تۀ هډو توجو نۀ کوې.“ ګورئ، حقيقت دا دے چې کله تاسو روژه نيولې وى نو هم په هغه وخت تاسو په خپلو فائدو پسې ګرځئ او د خپلو مزدورانو سره ظلم زياتے کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17679, 'Isaiah 58:4', 'Isaiah', 58, 4, '&nbsp;د داسې روژې نۀ څۀ فائده چې تاسو په کښې جنګ جګړې کوئ؟ کۀ تاسو داسې قسمه روژې ساتئ نو د دې توقع هم نۀ شئ کولے چې ستاسو آواز به آسمان ته ورسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17680, 'Isaiah 58:5', 'Isaiah', 58, 5, '&nbsp;ولې زۀ داسې روژه خوښوم څۀ چې انسان دې په کښې يوې ورځې دپاره خپل ځان عاجز کړى؟ او د لوخې د پاڼې په شان خپل سرونه ټيټ کړى او د ټاټ په جامو کښې په ايرو دپاسه څملى؟ تاسو دې ته روژه وايئ؟ دا ورځ به مالِک خُدائ ته قبوله وى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17681, 'Isaiah 58:6', 'Isaiah', 58, 6, '&nbsp;نه، زۀ چې څنګه روژه غواړم هغه داسې ده يعنې، د بې‌اِنصافۍ په زنځيرونو کښې راګېر خلق آزاد کړئ، د خپلو ماتحتو بوج کم کړئ. مظلومان آزاد کړئ، هر جغ مات کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17682, 'Isaiah 58:7', 'Isaiah', 58, 7, '&nbsp;اوږې خلق په خپل خوراک کښې شريک کړئ، او بې‌کوره غريبانانو له پناه ورکړئ. چا ته چې د جامو حاجت وى نو هغوئ له جامې ورکوئ او د خپلو خپلوانو سره د مدد کولو نه مۀ پټېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17683, 'Isaiah 58:8', 'Isaiah', 58, 8, '&nbsp;نو بيا به تاسو لکه د سحر د نمر په شان ځلېږئ، او ستاسو زخمونه به زر زر جوړ شى. او ستاسو صداقت به ستاسو نه مخکښې روان وى، او د مالِک خُدائ جلال به د وروستو نه ستاسو حِفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17684, 'Isaiah 58:9', 'Isaiah', 58, 9, '&nbsp;نو بيا به تاسو آواز کوئ او مالِک خُدائ به جواب درکوى، تاسو به د مدد دپاره سوال کوئ او مالِک خُدائ به فرمائى، ”زۀ حاضر يم.“ کۀ تاسو ظلم زياتے، بل ته ګوته نيول او د چُغلۍ خبرې پرېږدئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17685, 'Isaiah 58:10', 'Isaiah', 58, 10, '&nbsp;کۀ تاسو اوږو خلقو له روټۍ ورکړه او د مظلومانو مدد مو وکړو، نو بيا به ستاسو رڼا په تيارۀ کښې وځليږى، او چې ستاسو نه ګېرچاپېره کومه تيارۀ وى نو هغه به د غرمې په رڼا بدله شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17686, 'Isaiah 58:11', 'Isaiah', 58, 11, '&nbsp;نو زۀ به همېشه ستاسو لارښودنه کوم او په اوچ بيابان کښې به هم ستاسو حاجتونه پوره کوم. او زۀ به ستاسو وجود مضبوط کړم. تاسو به د يو داسې باغ په شان يئ چې ډېرې تېرې اوبۀ لرى، د هغه چينې په شان چې هيڅکله نۀ اوچيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17687, 'Isaiah 58:12', 'Isaiah', 58, 12, '&nbsp;او ستاسو هغه پخوانى کنډرات به دوباره آباد کړے شى. تاسو به تېرو نسلونو بنيادونه بيا آباد کړئ. او بيا به تاسو دېوالونه دوباره جوړولو والا، او لارې کوڅې دوباره آبادولو والا يادېږئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17688, 'Isaiah 58:13', 'Isaiah', 58, 13, '&nbsp;”کۀ تاسو د سبت ورځ يعنې زما په مقدسه ورځ کښې کاروبار نۀ کوئ، او دې ته د خوشحالۍ ورځ وايئ، دا د مالِک خُدائ مقدسه ورځ ګڼئ، د دې ادب کوئ او په دې ورځ خپل د روزانه کارونه نۀ کوئ او په خپلو فائدو پسې نۀ ګرځئ، او فالتُو خبرې نۀ کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17689, 'Isaiah 58:14', 'Isaiah', 58, 14, '&nbsp;نو بيا به تاسو د مالِک خُدائ سره په تعلق لرلو خوشحاله شئ. او زۀ به تاسو له لوئ عزت درکړم او په هغه ميراث به مو ماړۀ کړم د کوم لوظ چې ما ستاسو پلار نيکۀ يعقوب سره کړے دے. ما، مالِک خُدائ دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17690, 'Isaiah 59:1', 'Isaiah', 59, 1, '&nbsp;واورئ، د مالِک خُدائ لاس دومره وړوکے نۀ دے چې هغه تاسو بچ کولے نۀ شى او نۀ يې غوږ کُوڼ دے چې ستاسو آواز نۀ اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17691, 'Isaiah 59:2', 'Isaiah', 59, 2, '&nbsp;خو ستاسو ګناه د خُدائ پاک او ستاسو تر مينځه دېوال جوړ شوے دے. ستاسو ګناهونو د هغۀ مخ ستاسو نه پټ کړے دے، نو په دې وجه هغه ستاسو نۀ اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17692, 'Isaiah 59:3', 'Isaiah', 59, 3, '&nbsp;ځکه چې ستاسو لاسونه خونى، او ستاسو ګوتې په ګناه ککړې دى. ستا شونډې دروغژنې دى او خولۀ دې د بدعملۍ پس پس کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17693, 'Isaiah 59:4', 'Isaiah', 59, 4, '&nbsp;په عدالت کښې څوک هم د اِنصاف مقدمه نۀ چلوى، څوک هم د رښتيا دليلونه نۀ پېش کوى. خلق حقيقت نه خالى خبرو باندې اعتبار کوى او دروغ وائى، هغوئ د بدعملۍ نه اُميدواره شى او بيا ترېنه ګناه پېدا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17694, 'Isaiah 59:7', 'Isaiah', 59, 7, '&nbsp;بدعملۍ له هغوئ په منډه ځى، او د بې‌ګناه وينې تويولو دپاره تېزى کوى. د هغوئ خيالونه د ګناه دى، او هر چرته چې ځى نو تباهى او بربادى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17695, 'Isaiah 59:8', 'Isaiah', 59, 8, '&nbsp;نه هغوئ د امن لار پېژنى او نه د هغوئ په لارو کښې اِنصاف شته. هغوئ خپلې لارې کږې وږې جوړې کړې دى، نو هر څوک چې په دې لار ځى هغه امن نۀ پېژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17696, 'Isaiah 59:9', 'Isaiah', 59, 9, '&nbsp;نو ځکه اِنصاف زمونږ نه لرې دے او صداقت مونږ ته رارسى نه. مونږ د رڼا په انتظار کښې يُو، خو ګوره صرف تيارۀ راته ښکارى. مونږ د سپينې رڼا په اُميد کښې يُو خو په تکه توره تيارۀ کښې ګرځو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17697, 'Isaiah 59:10', 'Isaiah', 59, 10, '&nbsp;او مونږ د ړندو په شان لاس په دېوال باندې اېښودلو اېښودلو سره لار معلوموو، د هغه خلقو په شان چې بلکل سترګې نۀ لرى. مونږ د غرمې هم داسې تيندکونه خورو لکه چې شپه وى، مونږ په ژوندو کښې د مړو په شان يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17698, 'Isaiah 59:11', 'Isaiah', 59, 11, '&nbsp;مونږ ټول لکه د مېلوګانو غوريږُو، لکه د کونترو غور‌غور کوُو، مونږ د اِنصاف په انتظار کښې يُو خو شته دے نه، مونږ د خلاصون په انتظار کښې يُو خو دا زمونږ نه لرې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17699, 'Isaiah 59:12', 'Isaiah', 59, 12, '&nbsp;زمونږ جرمونه ستا په وړاندې انبار دى، او زمونږ ګناهونه زمونږ خلاف ګواهى کوى. مونږ ته د خپل بغاوت احساس شته او مونږ ته پته ده چې مونږ څومره ګناهګار يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17700, 'Isaiah 59:13', 'Isaiah', 59, 13, '&nbsp;مونږ د مالِک خُدائ خِلاف بغاوت کړے دے او د هغۀ مو اِنکار کړے دے، مونږ خپل خُدائ پاک ته شا کړې ده. زمونږ خبرې د ظلم او بغاوت نه ډکې دى. مونږ به دروغ جوړول او بيا به مو دغه دروغ په عمل کښې راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');